-- Polish remaining awkward prompt questions that sounded too mechanical or over-literal.
-- This migration updates by prompt id so it can repair databases where older wording was already applied.

START TRANSACTION;

CREATE TEMPORARY TABLE prompt_question_polish_075 (
    id VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PRIMARY KEY,
    question_en TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
    question_ko TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
    tip TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL
);


UPDATE prompts p
JOIN prompt_question_polish_075 r ON r.id = p.id
SET p.question_en = r.question_en,
    p.question_ko = r.question_ko,
    p.tip = r.tip
WHERE p.is_active = 1;

DROP TEMPORARY TABLE prompt_question_polish_075;

COMMIT;
